import type { MappedFlow } from '../planning/target-flows.js';
import { mermaidLabel } from './mermaid-label.js';

// RF-625, RF-508, DEC-134: the Mermaid sequence diagram of a target flow, generated by code from
// the checked flow; the model never writes Mermaid. The first participant is what starts the
// journey; each target component a step is mapped to is a participant, in order of first use. A
// step is a numbered message from the previous participant to its component; a step mapped to no
// component is left out of the diagram (the file lists it). Participant ids are generated (`p1`,
// `p2`, ...), never taken from names; `mask` hides secrets in every label before `mermaidLabel`
// codes it.

// RF-625
export function targetFlowDiagram(flow: MappedFlow, mask: (text: string) => string): string {
  const label = (text: string): string => mermaidLabel(mask(text));
  const ids = new Map<string, string>();
  const lines: string[] = [];
  const participant = (key: string, name: string): string => {
    const known = ids.get(key);
    if (known !== undefined) return known;
    const id = `p${String(ids.size + 1)}`;
    ids.set(key, id);
    lines.push(`  participant ${id} as ${label(name)}`);
    return id;
  };
  // Keys carry a prefix, so no component name can be taken for the trigger.
  let at = participant('trigger', flow.trigger === '' ? flow.title : flow.trigger);
  const messages: string[] = [];
  flow.steps.forEach((step, index) => {
    if (step.component === null) return;
    const to = participant(`component ${step.component}`, step.component);
    const text = step.action === '' ? step.text : step.action;
    messages.push(`  ${at}->>${to}: ${label(`${String(index + 1)}. ${text}`)}`);
    at = to;
  });
  if (flow.outcome !== '') messages.push(`  Note over ${at}: ${label(`Outcome: ${flow.outcome}`)}`);
  return ['sequenceDiagram', ...lines, ...messages, ''].join('\n');
}
